BEGIN READ ONLY;
SELECT coalesce(json_agg(t),'[]') FROM (SELECT a.id attempt_id,i.training_run_id,i.identity->>'split' split,count(r.sample_id) rows,count(DISTINCT r.payload->>'patient_id') patients,count(*) FILTER (WHERE r.payload->>'label'='0' AND r.payload->>'predicted'='0') tn,count(*) FILTER (WHERE r.payload->>'label'='0' AND r.payload->>'predicted'='1') fp,count(*) FILTER (WHERE r.payload->>'label'='1' AND r.payload->>'predicted'='0') fn,count(*) FILTER (WHERE r.payload->>'label'='1' AND r.payload->>'predicted'='1') tp,min((r.payload->>'threshold')::float8) threshold_min,max((r.payload->>'threshold')::float8) threshold_max FROM assessment_attempts a JOIN assessment_identities i ON i.id=a.identity_id LEFT JOIN assessment_results r ON r.attempt_id=a.id WHERE i.kind='evaluate' GROUP BY a.id,i.id ORDER BY a.id)t;
COMMIT;
